 b=p.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox']);page=b.new_page();errors=[];page.on('pageerror',lambda e:errors.append(str(e)));page.goto('http://127.0.0.1:8000/prototype-vgp.html#material');page.locator('#add').click();f=page.locator('#equipmentForm');f.locator('[name=identifier]').fill('INITIAL-FICTIF');f.locator('#equipmentType').select_option('__free__');f.locator('[name=designation]').fill('Fiche fictive');choose_missing_assignment(f);f.get_by_role('button',name='Enregistrer l’équipement').click();data=json.loads(page.evaluate("localStorage.getItem('vgp-prototype-v1')"));e=data['equipment'][0];e['designation']='Anneau importé m30 mal orthographié';e['typeId']='anneau-retournement';e['variantId']='';e['standardName']='Anneau de retournement';before=json.loads(json.dumps(e));page.evaluate('(d)=>localStorage.setItem("vgp-prototype-v1",JSON.stringify(d))',data);page.reload();page.locator('#list tbody tr').filter(has_text='DEMO-AR-001').get_by_role('button',name='Ouvrir',exact=True).click();page.locator('#edit').click();f=page.locator('#equipmentForm');expect(f.locator('[name=designation]')).to_have_value('Anneau de retournement');expect(f.locator('[name=designation]')).to_have_attribute('readonly','');expect(f.locator('[name=months]')).to_have_value(str(e['months']));expect(f.locator('[name=months]')).to_be_enabled();box=f.locator('[name=months]').bounding_box();assert box['width']<=150 and box['height']<=45;expect(page.locator('#setTypePeriod')).to_have_count(0);f.get_by_role('combobox',name='Variante / modèle',exact=True).click();f.locator('.select-popup:visible input').fill('m16');f.locator('.select-popup:visible').get_by_role('option',name='M16',exact=True).click();expect(f.locator('[name=designation]')).to_have_value('Anneau de retournement · M16');expect(f.locator('[name=months]')).to_have_value(str(e['months']));choose_missing_assignment(f);f.get_by_role('button',name='Enregistrer l’équipement').click();expect(page.locator('#editor')).not_to_be_visible();saved=json.loads(page.evaluate("localStorage.getItem('vgp-prototype-v1')"));e=saved['equipment'][0];assert e['designation']==e['standardName']=='Anneau de retournement · M16';assert e['originalDesignation']==before['designation'];assert e['controls']==before['controls'] and e['obligations']==before['obligations'] and e['months']==before['months'];assert e['namingHistory'][-1]['originalName']==before['designation'];page.reload();page.locator('#list tbody tr').filter(has_text='DEMO-AR-001').get_by_role('button',name='Ouvrir',exact=True).click();page.locator('#edit').click();expect(f.locator('[name=designation]')).to_have_value('Anneau de retournement · M16');assert not errors,errors;b.close()
